    /**
     * The slice of a dimension's total the customer is actually liable for.
     * <br><br>
     * A dimension without an allowance is chargeable in full. An allowance of
     * `inf` never runs out, so nothing is chargeable. A finite allowance which
     * the total has not passed is likewise not exhausted and nothing is
     * chargeable. Once a finite allowance is exhausted only the excess is
     * chargeable, and only when the plan permits overage; a plan that forbids
     * overage (or that never says whether it is permitted) charges nothing.
     */
    static chargeableUsage({
        dimension,
        total,
    }: {
        dimension?: Pick<ReadDimensionResponseData, 'usageEntitlement' | 'overageAllowed'>;
        total: number;
    }): number {
        const usage = Number.isFinite(total) ? Number(total) : 0;
        const entitlement = dimension?.usageEntitlement;
        if (entitlement === undefined || entitlement === null || (entitlement as unknown as string) === '') {
            // No allowance is carried by the dimension, everything measured is chargeable.
            return usage;
        }
        if ((entitlement as unknown as string) === 'inf') {
            // An unlimited allowance can never be exhausted.
            return 0;
